import {sorted,mean,fmt} from './analytics/stats.js';
import {compareRecent} from './analytics/attendance.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const shortDate=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
export function meetingTooltipHTML(r){return '<span class="tooltip-date">'+esc(date(r.date))+'</span>'+(r.name?'<span class="tooltip-name">'+esc(r.name)+'</span>':'')+'<strong class="tooltip-attendance">'+r.attendance+' <small>attendees</small></strong>';}
export function attendanceComparison(rows){const data=sorted(rows),c=compareRecent(data);return {...c,currentPeriod:data.slice(-3).map(r=>r.date),comparisonPeriod:data.slice(-6,-3).map(r=>r.date),currentAverage:c.current,previousAverage:c.baseline,absoluteDifference:c.change,percentDifference:c.percentChange};}
export function comparisonHTML(rows){const d=sorted(rows),c=attendanceComparison(d);if(!d.length)return '<p>Add Date and Attendance to your spreadsheet to see your club’s attendance trend. <a href="#sheets">View data template</a></p>';if(!c.available){const first=d[0].attendance,last=d.at(-1).attendance;return `<div class="attendance-comparison"><h3>${d.length===1?'One meeting is a starting point.':last<first?'Attendance ended lower than it started.':last>first?'Attendance ended higher than it started.':'Attendance ended where it started.'}</h3><p>${d.length===1?'Add another meeting to start seeing attendance changes.':`From ${first} attendees on ${date(d[0].date)} to ${last} on ${date(d.at(-1).date)}. Limited history: ${d.length} meetings. Six meetings are needed for a balanced last-three versus previous-three comparison.`}</p></div>`;}
return `<div class="attendance-comparison"><h3>${c.change<0?'Attendance has fallen recently.':c.change>0?'Attendance has risen recently.':'Recent attendance is unchanged.'}</h3><div class="comparison-periods"><div><span>Previous 3 meetings</span><strong>${fmt(c.baseline)}</strong><small>${date(c.comparisonPeriod[0])} – ${date(c.comparisonPeriod.at(-1))}</small></div><span class="comparison-arrow" aria-hidden="true">→</span><div><span>Last 3 meetings</span><strong>${fmt(c.current)}</strong><small>${date(c.currentPeriod[0])} – ${date(c.currentPeriod.at(-1))}</small></div></div><p>Average attendees per meeting · <strong>${fmt(Math.abs(c.change))} ${c.change<0?'fewer':c.change>0?'more':'change in'} attendees</strong>${c.percentChange==null?'. Percentage change is undefined because the previous average was zero.':` · ${fmt(Math.abs(c.percentChange))}% ${c.change<0?'decrease':c.change>0?'increase':'change'}.`}</p><p>Your last 3 meetings averaged <strong>${fmt(c.current)} attendees</strong>, compared with <strong>${fmt(c.baseline)}</strong> across the previous 3. Each period includes three meetings; this comparison alone does not explain the cause.</p></div>`;}
export function attendanceTrendChart(rows){const d=sorted(rows);if(!d.length)return comparisonHTML(d);const max=Math.max(4,Math.ceil(Math.max(...d.map(r=>r.attendance))/4)*4),start=Date.parse(d[0].date),end=Date.parse(d.at(-1).date),x=r=>8+(end===start?45:(Date.parse(r.date)-start)/(end-start)*87),y=r=>90-r.attendance/max*82;return `<div class="attendance-plot" role="group" aria-label="Attendance over time: ${d.length} meetings. Select a point or a meeting below for details."><span class="axis-title">Number of attendees</span><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${[0,1,2,3,4].map(i=>`<line x1="8" x2="95" y1="${90-i*20.5}" y2="${90-i*20.5}" class="attendance-grid"/>`).join('')}<polyline points="${d.map(r=>`${x(r)},${y(r)}`).join(' ')}" class="attendance-line"/></svg>${[0,1,2,3,4].map(i=>`<span class="attendance-tick" style="top:${90-i*20.5}%">${fmt(max*i/4)}</span>`).join('')}${d.map((r,i)=>`<button class="attendance-point" style="left:${x(r)}%;top:${y(r)}%" data-meeting-point="${i}" aria-label="${esc(date(r.date))}, ${esc(r.name||'Meeting')}, ${r.attendance} attendees"><span></span></button>`).join('')}${[...new Set([0,Math.floor((d.length-1)/2),d.length-1])].map((i,n)=>`<span class="attendance-date date-${n}" style="left:${x(d[i])}%">${shortDate(d[i].date)}</span>`).join('')}<div id="chart-point-tooltip" class="chart-point-tooltip" role="tooltip" hidden></div></div><p class="footnote">Meeting date · Every dot is one meeting. Tap a point or choose a meeting below.</p><label class="chart-meeting-label">Inspect a meeting<select id="chart-meeting">${d.map((r,i)=>`<option value="${i}"${i===d.length-1?' selected':''}>${esc(date(r.date))} · ${esc(r.name||'Meeting')} · ${r.attendance} attendees</option>`).join('')}</select></label><div id="meeting-tooltip" class="sr-only" role="status" aria-live="polite"></div>`;}
const fields=[['date','Date'],['name','Meeting name'],['attendance','Attendance',true],['new_members','New members',true],['returning_members','Returning members',true],['type','Meeting type'],['time','Meeting time'],['promotion','Promotion channels'],['days_promoted_before','Promotion started days before',true],['reach','Instagram reach before meeting',true],['signups','Signups before meeting',true],['special_event','Special event'],['notes','Notes'],['topic','Topic'],['members','Anonymous member IDs']];
export function historyColumns(rows){return fields.filter(([key])=>['date','attendance'].includes(key)||rows.some(r=>r[key]!=null&&r[key]!==''));}
export function historyRows(rows,ascending=false){const d=sorted(rows);return ascending?d:d.reverse();}
export function meetingHistoryTable(rows,ascending=false,expanded=false){const cols=historyColumns(rows),d=historyRows(rows,ascending),visible=expanded?d:d.slice(0,8);return `<div class="history-scroll" tabindex="0" role="region" aria-label="Meeting history, scroll horizontally for more columns"><table><caption class="sr-only">Meetings used in ClubPulse analysis</caption><thead><tr>${cols.map(([k,label,num])=>`<th scope="col"${num?' class="numeric"':''}${k==='date'?` aria-sort="${ascending?'ascending':'descending'}"`:''}>${k==='date'?`<button class="text-link" id="history-sort">Date ${ascending?'↑':'↓'}<span class="sr-only">; sort ${ascending?'newest':'oldest'} first</span></button>`:label}</th>`).join('')}</tr></thead><tbody>${visible.map(r=>`<tr${sorted(rows).slice(-3).some(m=>m.id===r.id)?' class="recent-meeting"':''}>${cols.map(([k,label,num])=>{let v=r[k];if(k==='date')v=date(v);else if(k==='promotion'&&Array.isArray(r.promotion_channels)&&r.promotion_channels.length)v=r.promotion_channels.join(' + ');else if(k==='members'&&Array.isArray(v))v=v.join('; ');else if(k==='special_event'&&v!=null)v=v?'Yes':'No';return `<td${num?' class="numeric"':''}>${k==='notes'&&v?.length>65?`<details class="history-note"><summary>${esc(v.slice(0,62))}…</summary><p>${esc(v)}</p></details>`:esc(v??'—')}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${d.length>8?`<button class="button history-expand" id="history-expand">${expanded?'Show first 8 meetings':`View all ${d.length} meetings`}</button>`:''}${!d.length?'<p>Import your meeting history to see it here.</p>':''}`;}
export function installInsightEvidence(root,rows,isDemo){const data=sorted(rows);root.classList.toggle('demo-narrative',isDemo);root.querySelector('.supporting-chart')?.remove();root.querySelector('.summary-metrics')?.remove();const heading=root.querySelector('.page-heading');heading.querySelector('h1').textContent=isDemo?'First, what happened?':'Your attendance, explained';heading.querySelector('p').textContent='See the trend. Inspect the meetings. Then explore possible reasons.';const section=document.createElement('section');section.className='insight-evidence';section.innerHTML=`<section id="attendance-evidence" tabindex="-1"><h2>Attendance over time</h2>${attendanceTrendChart(data)}${comparisonHTML(data)}</section><section class="meeting-history"><div class="history-heading"><div><h2>Meeting history</h2><p>See the data behind ClubPulse’s analysis. ClubPulse uses these meetings to calculate the insights above.</p></div><span>${data.length} meetings</span></div>${data.length?`<p class="footnote">${date(data[0].date)} – ${date(data.at(-1).date)} · Average attendance: ${fmt(mean(data.map(r=>r.attendance)))}</p>`:''}<div id="history-table"></div></section>`;heading.after(section);
const notice=root.querySelector('#notice-story');if(notice){notice.insertAdjacentHTML('afterbegin',`<h2>${isDemo?'What changed?':'What may be driving this?'}</h2>`);notice.querySelector('.notice-grid article')?.remove();notice.querySelectorAll('.notice-grid article').forEach(a=>a.insertAdjacentHTML('beforeend','<small>Last 3 meetings vs previous 3</small>'));}
const ask=root.querySelector('.ask-disclosure');if(notice&&ask)notice.after(ask);const idea=root.querySelector('.next-idea');if(ask&&idea)ask.after(idea);
const tooltip=root.querySelector('#meeting-tooltip'),selector=root.querySelector('#chart-meeting'),plot=root.querySelector('.attendance-plot'),floating=root.querySelector('#chart-point-tooltip');let pinned=false;
const hide=()=>{floating.hidden=true;root.querySelectorAll('[data-meeting-point]').forEach(p=>p.removeAttribute('aria-describedby'));};
const show=(i,visible=true)=>{const r=data[i];if(!r)return;selector.value=String(i);tooltip.textContent=date(r.date)+(r.name?' · '+r.name:'')+' · '+r.attendance+' attendees';root.querySelectorAll('[data-meeting-point]').forEach(p=>{p.setAttribute('aria-pressed',String(Number(p.dataset.meetingPoint)===i));p.removeAttribute('aria-describedby')});if(!visible)return;const point=root.querySelector('[data-meeting-point="'+i+'"]');floating.innerHTML=meetingTooltipHTML(r);floating.hidden=false;point.setAttribute('aria-describedby','chart-point-tooltip');const x=parseFloat(point.style.left)/100*plot.clientWidth,y=parseFloat(point.style.top)/100*plot.clientHeight,w=floating.offsetWidth,h=floating.offsetHeight;floating.style.left=Math.max(0,Math.min(plot.clientWidth-w,x-w/2))+'px';floating.style.top=(y-h-16>=0?y-h-16:y+18)+'px';};
if(selector){selector.onchange=()=>{pinned=true;show(Number(selector.value))};root.querySelectorAll('[data-meeting-point]').forEach(p=>{p.onmouseenter=()=>{pinned=false;show(Number(p.dataset.meetingPoint))};p.onfocus=()=>show(Number(p.dataset.meetingPoint));p.onclick=()=>{pinned=true;show(Number(p.dataset.meetingPoint))};p.onblur=()=>{if(!pinned)hide()}});plot.onmouseleave=()=>{if(!pinned)hide()};root.addEventListener('keydown',e=>{if(e.key==='Escape'){pinned=false;hide()}});root.addEventListener('pointerdown',e=>{if(!plot.contains(e.target)&&e.target!==selector){pinned=false;hide()}});show(data.length-1,false);}

if(isDemo){const history=root.querySelector('.meeting-history');history.querySelector('h2').textContent='What meetings caused that change?';history.querySelector('.history-heading p').textContent='These are the meetings ClubPulse is analyzing. The latest three are subtly highlighted.';const askSummary=ask?.querySelector('summary');if(askSummary)askSummary.innerHTML='Ask ClubPulse <span>Why did attendance fall?</span>';const investigate=root.querySelector('#investigate-change');if(investigate)investigate.textContent='Why did attendance fall?';if(idea){const title=idea.querySelector('h2');const replacement=document.createElement('h3');replacement.textContent=title.textContent;title.replaceWith(replacement);idea.insertAdjacentHTML('afterbegin','<h2>What should the club try next?</h2>');idea.querySelector('a').textContent='Try planning the next meeting →';}root.insertAdjacentHTML('beforeend','<section class="demo-conversion"><h2>Ready to analyze your own club?</h2><p>Upload your meeting history and ClubPulse will run the same analysis on your data.</p><a class="button primary" href="#import">Analyze My Club →</a> <a class="text-link" href="#demo">Restart Demo</a></section>');const answer=root.querySelector('#ask-answer');if(answer)new MutationObserver(()=>{const trace=[...answer.querySelectorAll('details')].find(d=>d.querySelector('summary')?.textContent==='Analysis used and limitations');if(trace)trace.open=true}).observe(answer,{childList:true,subtree:true});}
let ascending=false,expanded=false;const table=root.querySelector('#history-table'),render=()=>{table.innerHTML=meetingHistoryTable(data,ascending,expanded);table.querySelector('#history-sort').onclick=()=>{ascending=!ascending;render();table.querySelector('#history-sort').focus()};const button=table.querySelector('#history-expand');if(button)button.onclick=()=>{expanded=!expanded;render();table.querySelector('#history-expand').focus()};};render();}
